             saveFileDialog1.Filter = "Excel|*.xls|Excel 2010|*.xlsx";
   saveFileDialog1.Title = "Save list to File";  
   saveFileDialog1.ShowDialog();  

   // If the file name is not an empty string open it for saving.  
